// src/algolab/AlgoLab.tsx
// Лаборатория алгоритма: батч-прогон фотографий через РЕАЛЬНЫЙ пайплайн
// (MediaPipe + ONNX salient-object + importance map + WASM/WebGPU) на разных
// пресетах. Показывает сравнение «Было» (importance без общего ИИ-объекта —
// прежнее поведение) и «Стало» (с моделью главного объекта).
//
// Открывается по адресу /Melura/?algolab=1

import { useEffect, useRef, useState } from "react";
import { buildImportanceMap } from "../generator/utils/imageProcessing/importanceMap";
import { processImage } from "../generator/utils/imageProcessing/workerManager";
import type { ProcessingResult } from "../generator/utils/imageProcessing/types";
import { aiEngine } from "../generator/utils/ai/mediaPipeService";
import { salientObjectEngine } from "../generator/utils/ai/salientObjectService";

const BASE = (import.meta as any).env?.BASE_URL || "/";
const MAX_SIDE = 640; // ускоряем лабораторию, не влияя на качество сравнения

type Preset = { label: string; colors: number; detail: number };
const PRESETS: Preset[] = [
  { label: "Демократичный (12 цв / детал. 4)", colors: 12, detail: 4 },
  { label: "Стандарт (20 цв / детал. 6)", colors: 20, detail: 6 },
  { label: "Максимум (36 цв / детал. 9)", colors: 36, detail: 9 },
];

interface PhotoOutcome {
  variant: "old" | "new";
  previewUrl: string;
  heatUrl: string;
  colors: number;
}
interface PhotoState {
  name: string;
  origUrl: string;
  status: "idle" | "running" | "done" | "error";
  message?: string;
  outcomes: PhotoOutcome[];
  fgCoverage?: number | null;
}

async function loadImageData(url: string, maxSide: number): Promise<{ imageData: ImageData; w: number; h: number }> {
  const img = new Image();
  img.crossOrigin = "anonymous";
  await new Promise<void>((res, rej) => {
    img.onload = () => res();
    img.onerror = () => rej(new Error("load failed"));
    img.src = url;
  });
  let w = img.naturalWidth, h = img.naturalHeight;
  const scale = Math.min(1, maxSide / Math.max(w, h));
  w = Math.max(1, Math.round(w * scale));
  h = Math.max(1, Math.round(h * scale));
  const c = document.createElement("canvas");
  c.width = w; c.height = h;
  const ctx = c.getContext("2d")!;
  ctx.drawImage(img, 0, 0, w, h);
  return { imageData: ctx.getImageData(0, 0, w, h), w, h };
}

function imageDataToUrl(id: ImageData): string {
  const c = document.createElement("canvas");
  c.width = id.width; c.height = id.height;
  c.getContext("2d")!.putImageData(id, 0, 0);
  return c.toDataURL("image/png");
}

// importance 0..1 -> тепловая карта (синий->зелёный->жёлтый->красный)
function heatmapUrl(imp: Float32Array, w: number, h: number): string {
  const out = new ImageData(w, h);
  for (let i = 0; i < w * h; i++) {
    const v = Math.max(0, Math.min(1, imp[i]));
    let r: number, g: number, b: number;
    if (v < 0.5) { const t = v / 0.5; r = 0; g = Math.round(255 * t); b = Math.round(255 * (1 - t)); }
    else { const t = (v - 0.5) / 0.5; r = Math.round(255 * t); g = Math.round(255 * (1 - t * 0.5)); b = 0; }
    const p = i * 4;
    out.data[p] = r; out.data[p + 1] = g; out.data[p + 2] = b; out.data[p + 3] = 255;
  }
  return imageDataToUrl(out);
}

const noop = () => {};

export function AlgoLab() {
  const [photos, setPhotos] = useState<PhotoState[]>([]);
  const [presetIdx, setPresetIdx] = useState(1);
  const [running, setRunning] = useState(false);
  const abortRef = useRef(false);

  useEffect(() => {
    (async () => {
      try {
        const res = await fetch(`${BASE}algolab/manifest.json`);
        const names: string[] = await res.json();
        setPhotos(names.map((name) => ({
          name, origUrl: `${BASE}algolab/${encodeURIComponent(name)}`,
          status: "idle", outcomes: [],
        })));
      } catch {
        setPhotos([]);
      }
    })();
  }, []);

  async function runOne(idx: number, preset: Preset) {
    setPhotos((prev) => prev.map((p, i) => i === idx ? { ...p, status: "running", outcomes: [], message: "загрузка..." } : p));
    try {
      const { imageData } = await loadImageData(photos[idx].origUrl, MAX_SIDE);

      // AI: люди (MediaPipe) + универсальный объект (ONNX)
      let ai: any = null, fg: any = null;
      try { ai = await aiEngine.processImage(imageData); } catch {}
      try { fg = await salientObjectEngine.process(imageData); } catch {}

      const baseInput = {
        imageData,
        segmentationMask: ai?.segmentationMask || null,
        segmentationWidth: ai?.segmentationWidth || 0,
        segmentationHeight: ai?.segmentationHeight || 0,
        faceLandmarks: ai?.faceLandmarks || null,
      };

      // «Было»: без общего ИИ-объекта. «Стало»: с ним.
      const impOld = buildImportanceMap({ ...baseInput, foregroundMask: null });
      const impNew = buildImportanceMap({
        ...baseInput,
        foregroundMask: fg?.mask || null,
        foregroundWidth: fg?.maskW || 0,
        foregroundHeight: fg?.maskH || 0,
      });

      const outcomes: PhotoOutcome[] = [];
      for (const [variant, imp] of [["old", impOld], ["new", impNew]] as const) {
        const resProc: ProcessingResult = await processImage(
          new ImageData(new Uint8ClampedArray(imageData.data), imageData.width, imageData.height),
          preset.colors, preset.detail, noop, undefined, imp,
        );
        outcomes.push({
          variant,
          previewUrl: imageDataToUrl(resProc.previewImageData),
          heatUrl: heatmapUrl(imp, imageData.width, imageData.height),
          colors: Object.keys(resProc.colorPalette).length,
        });
      }

      setPhotos((prev) => prev.map((p, i) => i === idx
        ? { ...p, status: "done", outcomes, fgCoverage: fg?.coverage ?? null, message: undefined }
        : p));
    } catch (e: any) {
      setPhotos((prev) => prev.map((p, i) => i === idx ? { ...p, status: "error", message: e?.message || "ошибка" } : p));
    }
  }

  async function runAll() {
    setRunning(true); abortRef.current = false;
    const preset = PRESETS[presetIdx];
    for (let i = 0; i < photos.length; i++) {
      if (abortRef.current) break;
      await runOne(i, preset);
    }
    setRunning(false);
  }

  const box: React.CSSProperties = { background: "#0b1220", color: "#e2e8f0", minHeight: "100vh", padding: 16, fontFamily: "system-ui, sans-serif" };
  const btn: React.CSSProperties = { background: "#2563eb", color: "#fff", border: "none", borderRadius: 8, padding: "8px 14px", cursor: "pointer", marginRight: 8 };
  const cell: React.CSSProperties = { border: "1px solid #1e293b", borderRadius: 8, padding: 8, background: "#0f172a" };
  const imgS: React.CSSProperties = { width: "100%", display: "block", borderRadius: 6, imageRendering: "pixelated" };

  return (
    <div style={box}>
      <h1 style={{ marginTop: 0 }}>🧪 Лаборатория алгоритма Melura</h1>
      <p style={{ color: "#94a3b8", maxWidth: 900 }}>
        Слева «Было» — карта значимости и раскраска БЕЗ универсальной модели главного объекта
        (прежнее поведение, ИИ видит только людей). Справа «Стало» — с моделью U²-Net: объект
        (животное, предмет, цветок…) отделён от фона, граница не замыливается, важные детали сохранены.
        Красный на тепловой карте = «важно» (сюда идёт больше цветов/детализации), синий = фон.
      </p>
      <div style={{ margin: "12px 0" }}>
        <label style={{ marginRight: 8 }}>Пресет:</label>
        <select value={presetIdx} onChange={(e) => setPresetIdx(Number(e.target.value))}
          style={{ padding: 6, borderRadius: 6, marginRight: 12 }}>
          {PRESETS.map((p, i) => <option key={i} value={i}>{p.label}</option>)}
        </select>
        <button style={btn} disabled={running || photos.length === 0} onClick={runAll}>
          {running ? "Идёт прогон..." : `Прогнать все (${photos.length})`}
        </button>
        {running && <button style={{ ...btn, background: "#dc2626" }} onClick={() => { abortRef.current = true; }}>Стоп</button>}
      </div>

      {photos.length === 0 && <p style={{ color: "#f87171" }}>Нет фото в public/algolab/. Пересоберите проект.</p>}

      <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
        {photos.map((p, i) => (
          <div key={p.name} style={{ ...cell }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
              <strong>{i + 1}. {p.name}</strong>
              <span style={{ color: "#94a3b8", fontSize: 13 }}>
                {p.fgCoverage != null && <>объект занимает ~{Math.round(p.fgCoverage * 100)}% · </>}
                {p.status === "running" ? (p.message || "обработка...") : p.status}
                {p.status === "idle" && <button style={{ ...btn, marginLeft: 8, padding: "4px 10px" }} onClick={() => runOne(i, PRESETS[presetIdx])}>▶</button>}
              </span>
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 8 }}>
              <div>
                <div style={{ fontSize: 12, color: "#94a3b8", marginBottom: 4 }}>Оригинал</div>
                <img src={p.origUrl} style={imgS} />
              </div>
              {(["old", "new"] as const).map((variant) => {
                const o = p.outcomes.find((x) => x.variant === variant);
                const title = variant === "old" ? "Было (без ИИ-объекта)" : "Стало (с ИИ-объектом)";
                return (
                  <div key={variant}>
                    <div style={{ fontSize: 12, color: variant === "new" ? "#4ade80" : "#94a3b8", marginBottom: 4 }}>
                      {title}{o ? ` · ${o.colors} цв.` : ""}
                    </div>
                    {o ? (
                      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 4 }}>
                        <img src={o.heatUrl} style={imgS} title="Карта значимости" />
                        <img src={o.previewUrl} style={imgS} title="Раскраска" />
                      </div>
                    ) : <div style={{ color: "#475569", fontSize: 12 }}>—</div>}
                  </div>
                );
              })}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default AlgoLab;
